class GaussianLikelihood(LikelihoodModule):

    def __init__(self, ch_in, color_channels):
        super().__init__()
        self.parameter_net = nn.Conv2d(ch_in,
                                       2 * color_channels,
                                       kernel_size=3,
                                       padding=1)

    def distr_params(self, x):
        x = self.parameter_net(x)
        mean, lv = x.chunk(2, dim=1)
        params = {
            'mean': mean,
            'logvar': lv,
        }
        return params

    @staticmethod
    def mean(params):
        return params['mean']

    @staticmethod
    def mode(params):
        return params['mean']

    @staticmethod
    def sample(params):
        p = Normal(params['mean'], (params['logvar'] / 2).exp())
        return p.rsample()

    def log_likelihood(self, x, params):
        logprob = -0.5 * (((x - params['mean'])**2) / (params['logvar'].exp()) + params['logvar'])
        return logprob

