class LogLinearNoise(Noise, nn.Module):
    """
    Log Linear noise schedule built so that 1 - 1/e^(n(t)) interpolates between 0 and ~1
    when t goes from 0 to 1. Used for absorbing

    Total noise is -log(1 - (1 - eps) * t), so the sigma will be (1 - eps) * t
    """
    def __init__(self, eps=1e-3, learnable=True):
        super().__init__()
        self.logit_eps = nn.Parameter(torch.tensor(np.log(eps) - np.log(1 - eps))) if learnable else torch.tensor(np.log(eps) - np.log(1 - eps))
        self.empty = nn.Parameter(torch.tensor(0.0))

    def rate_noise(self, t):
        eps = torch.sigmoid(self.logit_eps)
        return (1 - eps) / (1 - (1 - eps) * t)

    def total_noise(self, t):
        eps = torch.sigmoid(self.logit_eps)
        return -torch.log1p(-(1 - eps) * t)

